create table if not exists public.alicia_interpreter_knowledge (
  id uuid primary key default gen_random_uuid(),
  knowledge_type text not null check (knowledge_type in (
    'categories','merchant_aliases','merchant_dictionary',
    'phrase_rules','item_rules','extraction_fields','interpretation_strategy'
  )),
  knowledge_key text not null,
  payload jsonb not null,
  locale text not null default 'pt-BR',
  priority smallint not null default 100,
  active boolean not null default true,
  source text not null default 'alicerce-interpreter',
  source_version text not null default '2026-11-04',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (knowledge_type, knowledge_key, locale)
);
create index if not exists alicia_interpreter_knowledge_active_idx
  on public.alicia_interpreter_knowledge (active, locale, priority);
alter table public.alicia_interpreter_knowledge enable row level security;
revoke all on table public.alicia_interpreter_knowledge from public, anon, authenticated;
grant select on table public.alicia_interpreter_knowledge to service_role;
